css:
/* Container styles */
.container {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 300px; /* Fixed height */
  width: 160px; /* Fixed width */
  border: 4px solid black; /* Border */
  border-radius: 1rem; /* Rounded corners */
  background-color: #f9fafb; /* Light gray background */
  box-shadow: 5px 5px 2.5px 6px rgb(209, 218, 218); /* Shadow effect */
}
.time {
  font-size: 2.5rem;
  margin: 1.5rem 0 -12px;
}
.date {
  font-size: 12px;
}
.fingerprint {
  position: absolute;
  bottom: 3rem;
}
.phone {
  position: absolute;
  bottom: 10px;
  left: 10px;
  padding: 4px;
  background-color: rgb(209, 218, 218);
  border-radius: 6px;
}
.camera {
  position: absolute;
  bottom: 10px;
  right: 10px;
  padding: 4px;
  background-color: rgb(209, 218, 218);
  border-radius: 6px;
}
/* Top border styles */
.top-border {
  border: 1px solid black; /* Border */
  background-color: black; /* Black background */
  width: 80px; /* Width of the top border */
  height: 8px; /* Height of the top border */
  border-bottom-left-radius: 1rem; /* Rounded bottom corners */
  border-bottom-right-radius: 1rem; /* Rounded bottom corners */
}

/* Right border styles */
.right-border {
  position: absolute;
  border: 4px solid black; /* Border */
  right: -8px; /* Positioning */
  border-radius: 0.375rem; /* Rounded corners */
}

/* Top right border */
.right-border.top {
  top: 56px; /* Positioning */
  height: 28px; /* Height of the top right border */
}
